def exactRoot(n, m):
    def cmp_pow(r):
        p = 1
        for _ in range(n):
            p *= r
            if p > m:
                return 1
        return 0 if p == m else -1

    lo, hi = 1, min(m, 46341) if n > 1 else m
    while lo <= hi:
        mid = (lo + hi) // 2
        c = cmp_pow(mid)
        if c == 0:
            return mid
        if c < 0:
            lo = mid + 1
        else:
            hi = mid - 1
    return -1
